from pathlib import Path
import json,csv
P=Path(__file__).resolve().parent;e=json.loads((P/'edits.json').read_text());n=json.loads((P/'notes.json').read_text())
def p(k,t):e[f'A0567-B{k:04d}']=t
p(41,'大先知艾尔德拉德·乌瑟兰曾协助阻止赫鲁德侵入塞姆罕方舟世界；若未加阻止，这艘宏伟的方舟便可能化为腐烂残渣。')
p(79,'赫鲁德最显著的特征，是被称为“萨阿克”，意为“见雾”的熵场。这种神秘的扭曲力场源于赫鲁德自身的生理活动，环绕每一个个体，而非仅限战士。其作用被形容为具有寄生性质，能够改变时空结构，产生无法预测的影响。')
p(81,'萨阿克似乎具有多种用途：掩护赫鲁德的行踪，使周围事物老化、削弱敌人，并抵挡攻击。它扭曲光线与时间，让赫鲁德呈现为一柱闪烁空气中若隐若现的黑影。即便身处明亮环境，它们也能借阴影隐匿；静止时，更几乎无法察觉。')
p(83,'判断赫鲁德是否在附近，视觉以外的感知方式或许更可靠。萨阿克似乎会改变大气构成，加快粒子运动，使空气变得黏稠。致命的寒冷或难以忍受的高热，往往先于赫鲁德出现。萨克特拉达深渊战役中，钢铁勇士发现，热成像较适合探测、瞄准赫鲁德，因为萨阿克会导致环境中的热量大量流失；但即便如此，异常加速的原子活动仍会形成一片热晕，遮蔽它们的身形。这些诡异的时间膨胀效应，甚至使大先知无法循命运之线追踪赫鲁德。因此，艾达灵族称它们为“躲避老妪者”。')
p(85,'萨阿克能令赫鲁德的敌人急速衰老。萨克特拉达深渊战役中，钢铁勇士哈拉基斯刚与赫鲁德接触，臂铠的陶钢便蚀出凹坑，仿佛已在风雨中暴露五千年。他随即倒下，崩解的血肉从护甲裂口中流出；据说，这一切还不到一秒。同样参加该战役的福特雷顿，也发现自己的护甲在转瞬之间，便经历了一个世纪的腐朽。')
p(87,'萨阿克也会使周遭环境老化，作物化为尘埃，人类过早衰老。其效应能够叠加：聚集在近处的赫鲁德越多，作用就越强。大规模迁徙时，赫鲁德仅凭自身存在，就足以摧残整个世界。萨克特拉达深渊战役中，大批赫鲁德聚集于钢铁勇士堡垒下方的天然水道，汇合后的萨阿克覆盖堡垒，将其浸没于时间辐射。工事迅速衰败，仿佛已荒废数千年，随后便被赫鲁德轻易突破。')
p(89,'入侵哈科纳特时，赫鲁德制造了一道时间裂隙。残酷扭曲的空间几何杀死许多星辰幻影；一道失控的时间涡流更刺穿战团长的战斗驳船舰桥，令奥玛顿·提瑞西阿斯双目失明。')
p(91,'萨阿克还能抵御攻击。进入其中的弹丸会发生无法预料的变化：偏离弹道、加速至匪夷所思的速度、提前引爆，或分解成一阵原子雨。')
p(93,'赫鲁德自身的身体与造物，似乎不受萨阿克加速老化的影响。但个体一旦死亡，尸体便会迅速衰败、液化，可能是因为失去了抵御自身熵场的保护。')
p(96,'赫鲁德行事隐秘，常与其他种族生活在同一地区，却不为对方所知。帝国流传着许多故事，声称城市地下、星舰引擎群下方、古老巢都的层间缝隙，隐藏着不为人知的族群。这类传闻往往被视为吓唬孩童的怪谈。')
p(98,'赫鲁德的隧道城市称为“朱恩塔克”，往往建在人类人口最密集的聚居中心附近。隧道穿过行星岩层，绵延数百公里，巢穴中的房室、通道彼此相接，很少设门。墙面被形容为玻璃般光滑，似乎不受赫鲁德世界持续震动的影响。已知内部设施包括礼拜室、家庭洞穴与档案室。')
p(100,'赫鲁德有迁徙的习性。“波哈”指人口增长触发的大规模迁徙：当部落成员超过一定数量，一部分个体便会离群，藏入运输船或太空废船，前往远方建立新部落。它们也拥有自己的迁徙舰。另有些赫鲁德终生漂泊，甚至在帝国星舰甲板之间，形成繁盛的游牧国度。')
p(102,'赫鲁德是拾荒种族，“受人尊敬的打捞者夜行联合体”便是例证。它们擅长利用手边的一切资源，拼装出五花八门的武器与装置。')
p(104,'赫鲁德具有强烈的部落意识，极重祖先与家族纽带。不过，据推测，迁徙时分出的群体通常缺乏远距离联络手段，此后便很少往来。赫鲁德也会将人类等其他种族带入部落，赋予其“赞哈德”的身份，即兼具奴隶与宠物性质的角色。其聚落中还发现过基因窃取者感染者。')
p(106,'赫鲁德极重档案，对记录保存的细致近乎无以复加，积累了大量历史、文化与技术资料。它们将档案珍藏于巢穴中的专门区域，遭入侵时会奋力保卫。迁徙必带之物中，有一项叫“拉希德”，又称“大部落”，指的便是整个部落积累的知识。')
p(109,'按赫鲁德的信仰，它们由斯拉哈伊诸神创造，原本应在阳光下生活、繁衍。后来，神祇卡赫预见到将来的危险，才将它们改造为夜间活动的拾荒种族。')
p(111,'赫鲁德崇拜仁慈的斯拉哈伊诸神，意为“最古老者”。其中包括卡赫、一名有角的猎手、一位赤手神祇、笑语弄臣，以及持锤的工匠。他们曾与雅姆科——“镜像魔鬼”——开战；除卡赫外，众神或遭杀戮，或被致残，或被迫逃亡。')
p(113,'赫鲁德传说称，斯拉哈伊诸神中，如今唯有卡赫尚存，又称“徘徊者”。约五十万年前，卡赫告诉赫鲁德，自己还有其他伟业要完成，随后便消失了。他曾许诺，将在“拉希德斯凯”到来时回归，重新召集各部落。届时，赫鲁德将合而为一，与雅姆科展开最后决战。')
p(115,'审判官马图林·拉莱注意到，赫鲁德的神系与灵族等其他异形种族的神系存在相似之处。')
p(120,'赫鲁德最常用的远程武器是“相位火枪”（Fusil，原稿又称连射枪、连发枪），一种采用相位等离子或亚空间等离子技术的火枪。其射出的绿色能量在现实与亚空间间闪现，可在目标内部重新显现，绕过护甲，从体内摧毁受害者。审判官克里普特曼认为，这种武器只是将热熔与等离子技术结合，便能喷出比恒星更炽热的火柱。相位火枪是少数偶尔流入帝国市场的赫鲁德造物，需求甚高。黑市货品通常经过改装，可使用帝国等离子能量匣；但若内部机构严重损坏，人类便无法修复。')
p(122,'萨克特拉达深渊战役中，赫鲁德还使用了许多能够扭曲时空的武器。它们制造集中的时间涡流，让目标迅速衰老、由内而外腐烂；一些火炮则将目标沿自身时间线推移千分之几秒，使其与行星运动失去同步，结果与周围物体嵌合在一起。近战战士持有成对的光刃，刃上烟雾翻卷，带着熵解之力。钢铁勇士试图格挡时，武器一经接触便老化崩毁；被刺中的战士，身体则扭成不可能的形状，随即爆裂。还有人急速返老还童，乃至身体排斥星际战士植入器官。赫鲁德还投入其他奇异兵员与兵器：配备球茎状火炮、肢体柔韧的步行机，身着粗糙活体护甲的战士，以及难辨究竟是机械、血肉还是二者混合的怪异造物。')
p(124,'赫鲁德以晶体棱镜储存、传递信息，并用未知手段，在晶体内部刻入文字与符号。')
p(129,'赫鲁德似乎采用多种星际航行方式：一种奇异的亚空间技术，使它们能步行往来于不同世界；它们也使用迁徙舰、由覆甲菌质聚合成的怪船等星际船只。部分舰船具有类似萨阿克的熵场，可扭曲时空、使周围事物老化，并抵挡攻击。')
p(131,'赫鲁德还有一种交通方式，被形容为将时间能量聚成矛状，推动自身穿越时空。萨克特拉达深渊战役中，古甘濒临崩溃，赫鲁德撤离行星。它们的多支先遣队反复偷渡帝国舰船，穿越虚空，以某种未知手段悄无声息地穿过舰壁。帝国部队因此组织清剿小队，每小时巡查甲板的偏僻角落，搜捕潜入者。')
p(133,'撤离垂死的古甘时，一艘大陆般庞大的赫鲁德巨舰破土而出。它以行星本身的物质作燃料，挣脱大地。巨舰进入太空后，迁徙舰在其周围组成空心立方体般的阵列，刺眼的电弧状光芒跃出，将各舰与巨舰相连。转瞬之间，所有赫鲁德船只都消失了。它们离去时撕裂时空，原处随即发生时间坍缩。冲击波席卷钢铁勇士舰船，造成无法预料的时间畸变：有的舰体瞬间老化百万年；有的全体船员数秒内化为尘埃；还有的以难以想象的速度向后加速，直至消失，或离散为粒子。')
p(136,'2021年推出的《涅克罗蒙达》死亡地带下巢市场模型套装中，枪架上的一把火枪，与第三版及第六版规则书描绘的赫鲁德相位火枪十分相似。')
p(138,'An apparent Hrud Fusil 一把疑似赫鲁德相位火枪的模型')
p(141,'不同资料对赫鲁德的具体外形说法不一；共同点是，它们习惯披戴斗篷。')
p(145,'1998年出版的《战锤40,000》第三版规则书，首次刊登赫鲁德图像：一种弯腰蹲伏、身形矮小的生物，裹着破布，拖着鼠类般的尾巴。2012年的第六版规则书再次采用相近形象，画中赫鲁德披着斗篷，手持长枪，尾巴外露。')
p(149,'2006年背景设定书《异形学》采用另一种相矛盾的外形：没有尾巴、直立行走的沼泽怪物，四肢细长柔韧，真貌藏在由腐败污物构成的褴褛斗篷之下。2017年小说《佩图拉博：奥林匹亚之锤》也采用这一描述。')
p(151,'2021年的《异形志》（Liber Xenologis）将资料冲突本身纳入设定：以书中人物的视角说明，帝国关于赫鲁德外形的报告差异极大，并用一则经过删隐处理的条目，取代明确的赫鲁德图像。')
p(153,'Redacted Hrud in Liber Xenologis 《异形志》中经过删隐处理的赫鲁德条目')
n.update({'A0567-B0041':'Eldrad Ulthran、Farseer 分别采用 GW-09/GW-10 第6页的艾尔德拉德·乌瑟兰、大先知；前稿别名埃尔德拉德·乌斯兰保留于原译栏。','A0567-B0083':'particular motion 疑为 particle motion，按原子活动上下文译为粒子运动；time-dialatory 为时间膨胀，避免读成普通延迟。','A0567-B0085':'mere moments 为转瞬，不是原译几分钟；第一位战士不到一秒死亡为独立事件。','A0567-B0087':'原文叠加强度取决于近处聚集的赫鲁德数量，不只是个体之间距离变小。','A0567-B0098':'玻璃般光滑仅为表面描述，不擅自认定墙体材料是玻璃。','A0567-B0111':'红手、弄臣、工匠等保持神话描述，不无依据直接等同灵族具体神名。','A0567-B0120':'Fusil 不含连射或连发之义，按此篇明确的相位技术暂定相位火枪，保留原别名；并非官方已核名。','A0567-B0122':'twin blades of light 为成对光刃，原译双刃轻烟错误；千分之几秒而非恰好千分之一秒；age backwards 指返老还童。','A0567-B0133':'space-bourne 指进入太空，不是前往太空边界；temporal collapse 是时间坍缩，不是暂时崩溃。','A0567-B0136':'模型与插画相似属于原文推测，未断言官方确认；apparent 因此译疑似。','A0567-B0145':'cloaked 为披斗篷，不是隐形。','A0567-B0151':'redacted 指删隐信息，不是节选修订；Liber Xenologis 暂译异形志，区别 Xenology 异形学。不同版外形差异保留。'})
rows=list(csv.DictReader((P/'terms.tsv').open(),delimiter='\t'));cols=list(rows[0]);by={r[cols[0]].casefold():r for r in rows}
for en,zh in [('Temporaferrox','Temporaferrox（暂保留英文）'),('Troglydium hrudii','Troglydium hrudii（学名）'),('Those Who Evade the Crone','躲避老妪者'),('Janus Draik','贾纳斯·德雷克'),("Sak’trada Deeps",'萨克特拉达深渊'),('Hrud Rising','赫鲁德叛乱'),('Haakonath','哈科纳特'),('Damhal','达姆哈尔'),('Keep Extremis','极端堡'),('Tavalar','塔瓦拉'),('Kashann Xeno Riders','卡尚异形骑兵'),('Ursula Spinal','乌苏拉之脊'),('Paternus Gloriem','荣耀之父号'),('Selebor Mathias','塞莱博尔·马蒂亚斯'),('Cinchare','辛查尔'),('Ursarkar E. Creed','乌萨卡·E.克里德'),('Laevenir Archipelago','拉维尼尔群岛'),('Ouroboros','乌洛波洛斯'),('Liber Historica Vangelia','万杰利亚历史册'),("Mortenken’s World",'莫滕肯世界'),('Olfric','奥弗里克'),('Last Chancers','最后机会'),("Es’Tau",'艾斯钛'),('Saim-Hann','塞姆罕'),('Ulumeathi','乌卢梅亚蒂人'),('Draxians','德拉西安'),('Delphic','德尔斐'),('Mordant Acid Dogs','莫丹特强酸犬'),('Vesalius','维萨里号'),('Igori','伊戈里'),('Sharle Darvus','莎尔·达维斯'),('Ssaak','萨阿克'),('Harrakis','哈拉基斯'),('Fortreidon','福特雷顿'),('Omadon Tiresias','奥玛顿·提瑞西阿斯'),('Juuntak','朱恩塔克'),('Poh-ha','波哈'),("Respectable Salvager’s Nocturnal Consortium",'受人尊敬的打捞者夜行联合体'),('Zanhaad','赞哈德'),('Raheed','拉希德'),('Masstribe','大部落'),('Slah-haii','斯拉哈伊'),('Yaam-khoh','雅姆科'),('Raheed-skeh','拉希德斯凯'),('Maturin Ralei','马图林·拉莱'),('Fusil','相位火枪'),('Gugann','古甘'),('Liber Xenologis','异形志')]:
 by.setdefault(en.casefold(),dict(zip(cols,[en,zh,'暂定·官方待核','所给英文底稿','篇0567','专名按本篇英文区分；保持神话、推测及版本限定，不作官方认证。'])))
u9='https://assets.warhammer-community.com/chi_06-05_wh40k_core%26key_munitorum_field_manual-5mrlucr2t1-fkybzzzoce.pdf';u10='https://assets.warhammer-community.com/eng_warhammer40000_munitorum_field_manual_march_2025-cims9ya3sg-s8j9m2haae.pdf'
for en,zh in [('Eldrad Ulthran','艾尔德拉德·乌瑟兰'),('Farseer','大先知')]:by[en.casefold()]=dict(zip(cols,[en,zh,'官方已核对',f'GW-09 {u9}；GW-10 {u10}','两版PDF均第6页','中英官方清单逐项核对；普通 prophet 不因此一律译大先知。']))
with (P/'terms.tsv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=cols,delimiter='\t');w.writeheader();w.writerows(by.values())
for fn,obj in [('edits.json',e),('notes.json',n)]:(P/fn).write_text(json.dumps(obj,ensure_ascii=False,indent=2))
rv=set(json.loads((P/'reviewed.json').read_text()))|{567};(P/'reviewed.json').write_text(json.dumps(sorted(rv)))
(P/'partial_progress.json').write_text(json.dumps({'article':567,'read_through_block':153,'complete':True},ensure_ascii=False,indent=2))
print('567 complete')
